package com.ykt.assistant;

import android.app.*;
import android.view.*;
import android.widget.*;
import android.graphics.drawable.GradientDrawable;
import java.util.*;

/** Checkbox plus separate recipient editor, shared by settings, checkin and both answer screens. */
final class SyncControls extends LinearLayout {
    private final Activity activity;private final SyncSettings settings;private final String kind;private final Runnable changed;private final CheckBox check;private final TextView edit;private boolean refreshing;private Dialog picker;
    SyncControls(Activity activity,SyncSettings settings,String kind,Runnable changed){super(activity);this.activity=activity;this.settings=settings;this.kind=kind;this.changed=changed;setGravity(Gravity.CENTER_VERTICAL);setTag("sync-row:"+kind);check=new CheckBox(activity);check.setText(SyncSettings.CHECKIN.equals(kind)?"同步签到":"同步答题");check.setTextSize(13);check.setTextColor(0xff263d32);check.setMinHeight(dp(44));check.setButtonTintList(android.content.res.ColorStateList.valueOf(0xff2c5846));check.setTag("sync-check:"+kind);addView(check,new LayoutParams(0,-2,1));edit=new TextView(activity);edit.setTextSize(12);edit.setTextColor(0xff2c5846);edit.setGravity(Gravity.CENTER);edit.setMinHeight(dp(44));edit.setPadding(dp(8),0,dp(4),0);edit.setTag("sync-edit:"+kind);addView(edit,new LayoutParams(-2,-2));check.setOnCheckedChangeListener((v,value)->{if(refreshing)return;settings.enabled(kind,value);if(changed!=null)changed.run();refresh();});edit.setOnClickListener(v->choose());refresh();}
    void label(String value){check.setText(value);}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    void refresh(){refreshing=true;setVisibility(settings.available()?VISIBLE:GONE);check.setChecked(settings.enabled(kind));check.setEnabled(isEnabled()&&(!settings.eligible().isEmpty()||settings.enabled(kind)));edit.setText("修改账号（"+settings.selected(kind).size()+"）");edit.setEnabled(isEnabled());refreshing=false;}
    @Override public void setEnabled(boolean enabled){super.setEnabled(enabled);if(check!=null)refresh();}
    private void choose(){
        if(!settings.available())return;picker=new CardDialog(activity);LinearLayout panel=new LinearLayout(activity);panel.setOrientation(VERTICAL);panel.setPadding(dp(20),dp(16),dp(20),dp(20));LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);TextView title=new TextView(activity);title.setText("选择同步账号");title.setTextSize(20);title.setTextColor(0xff263d32);header.addView(title,new LayoutParams(0,dp(44),1));header.addView(CardDialog.closeButton(activity,picker,"同步账号"),new LayoutParams(dp(44),dp(44)));panel.addView(header);TextView hint=new TextView(activity);hint.setText("仅列出同服务器的其他账号，默认全部选择。");hint.setTextSize(12);hint.setTextColor(0xff7e8d81);panel.addView(hint);LinearLayout list=new LinearLayout(activity);list.setOrientation(VERTICAL);panel.addView(list);Set<String> selected=new HashSet<>();for(AccountStore.Account a:settings.selected(kind))selected.add(a.key);List<AccountStore.Account> eligible=settings.eligible();List<CheckBox> choices=new ArrayList<>();for(AccountStore.Account a:eligible){CheckBox c=new CheckBox(activity);c.setText(a.name);c.setTextSize(14);c.setTextColor(0xff263d32);c.setButtonTintList(android.content.res.ColorStateList.valueOf(0xff2c5846));c.setChecked(selected.contains(a.key));c.setMinHeight(dp(48));c.setTag("sync-account:"+a.key);choices.add(c);list.addView(c);}if(eligible.isEmpty()){TextView empty=new TextView(activity);empty.setText("暂无同服务器的其他账号");list.addView(empty);}Button all=new FlatButton(activity);all.setText("全选");all.setAllCaps(false);all.setTextColor(0xff2c5846);GradientDrawable pale=new GradientDrawable();pale.setColor(0xffedf3e9);pale.setCornerRadius(dp(12));all.setBackground(pale);all.setOnClickListener(v->{for(CheckBox c:choices)c.setChecked(true);});list.addView(all);Button save=new FlatButton(activity);save.setText("使用所选账号");save.setAllCaps(false);save.setTextColor(0xffffffff);GradientDrawable green=new GradientDrawable();green.setColor(0xff2c5846);green.setCornerRadius(dp(12));save.setBackground(green);save.setOnClickListener(v->{Set<String> keys=new HashSet<>();for(int i=0;i<eligible.size();i++)if(choices.get(i).isChecked())keys.add(eligible.get(i).key);settings.select(kind,keys);picker.dismiss();refresh();if(changed!=null)changed.run();});panel.addView(save);picker.setContentView(panel);picker.show();
    }
    @Override protected void onDetachedFromWindow(){if(picker!=null)picker.dismiss();super.onDetachedFromWindow();}
}
